import sympy

def solve():
    # Grid size
    N = 4
    # The grid is 4x4, total 16 cells.
    # Represent states as bitmasks of length 16.
    # No two coins are orthogonally adjacent.
    # Each 2x2 square has at least one coin.

    # Cells (r, c) where 0 <= r, c < 4.
    # Represented by index r * 4 + c

    adj = []
    for r in range(N):
        for c in range(N):
            neighbors = []
            if r > 0: neighbors.append((r-1)*N + c)
            if r < N-1: neighbors.append((r+1)*N + c)
            if c > 0: neighbors.append(r*N + (c-1))
            if c < N-1: neighbors.append(r*N + (c+1))
            adj.append(neighbors)

    # Precompute 2x2 squares
    squares = []
    for r in range(N-1):
        for c in range(N-1):
            squares.append([r*N + c, r*N + c+1, (r+1)*N + c, (r+1)*N + c+1])

    count = 0
    # There are 16 cells, so 2^16 = 65536 possibilities.
    # We can iterate through all and check conditions.
    for i in range(1 << 16):
        # Condition 1: No two coins are orthogonally adjacent
        valid = True
        for r in range(N):
            for c in range(N):
                idx = r*N + c
                if (i >> idx) & 1:
                    for neighbor in adj[idx]:
                        if (i >> neighbor) & 1:
                            valid = False
                            break
                if not valid: break
            if not valid: break

        if not valid:
            continue

        # Condition 2: Each 2x2 square has at least one coin
        for sq in squares:
            has_coin = False
            for cell in sq:
                if (i >> cell) & 1:
                    has_coin = True
                    break
            if not has_coin:
                valid = False
                break

        if valid:
            count += 1

    return count

result = solve()
print(f"ANSWER: {sympy.latex(result)}")
