    # Indices 0-15 correspond to (row, col) = (i // 4, i % 4)

    count = 0

    # Precompute orthogonal adjacencies
    adj = []
    for r in range(4):
        for c in range(4):
            neighbors = []
            if r > 0: neighbors.append((r-1)*4 + c)
            if r < 3: neighbors.append((r+1)*4 + c)
            if c > 0: neighbors.append(r*4 + (c-1))
            if c < 3: neighbors.append(r*4 + (c+1))
            adj.append(neighbors)

    # Precompute 2x2 squares (top-left corners)
    squares_2x2 = []
    for r in range(3):
        for c in range(3):
            squares_2x2.append([r*4 + c, r*4 + c + 1, (r+1)*4 + c, (r+1)*4 + c + 1])

    # Iterate through all 2^16 configurations
    for i in range(1 << 16):
        # Condition 1: No two coins are orthogonally adjacent
        valid_adj = True
        for pos in range(16):
            if (i >> pos) & 1:
                for neighbor in adj[pos]:
                    if (i >> neighbor) & 1:
                        valid_adj = False
                        break
            if not valid_adj: break

        if not valid_adj:
            continue

        # Condition 2: Each 2x2 square has at least one coin
        valid_squares = True
        for sq in squares_2x2:
            has_coin = False
            for pos in sq:
                if (i >> pos) & 1:
                    has_coin = True
                    break
            if not has_coin:
                valid_squares = False
                break

        if valid_squares:
            count += 1

    return count

